-- Generated by tools/GenerateRptViews.py; edit the generator, not this file.
-- One row per task. A task belongs to one project. TaskKey looks like WEB-42. Needs project.view.
CREATE VIEW rpt.Task
AS
SELECT
    t.Id AS TaskId,
    t.TaskKey AS TaskKey,
    t.Title AS TaskTitle,
    t.ProjectId AS ProjectId,
    p.Name AS ProjectName,
    p.ClientId AS ClientId,
    c.Name AS ClientName,
    tt.Name AS TaskType,
    ts.Name AS TaskStatus,
    ts.SystemCode AS TaskStatusCode,
    tp.Name AS Priority,
    t.AssignedUserId AS AssignedUserId,
    a.DisplayName AS AssignedTo,
    t.EstimatedHours AS EstimatedHours,
    t.StartDate AS StartDate,
    t.DueDate AS DueDate,
    CAST(t.CompletedAt AS DATE) AS CompletedDate,
    t.IsBillable AS IsBillable,
    CAST(t.CreatedAt AS DATE) AS CreatedDate
FROM crm.ClientTask AS t
JOIN crm.ClientProject AS p ON p.TenantId = t.TenantId AND p.Id = t.ProjectId
JOIN crm.Client AS c ON c.TenantId = p.TenantId AND c.Id = p.ClientId
JOIN lkp.TaskStatus AS ts ON ts.TenantId = t.TenantId AND ts.Id = t.TaskStatusId
LEFT JOIN lkp.TaskType AS tt ON tt.TenantId = t.TenantId AND tt.Id = t.TaskTypeId
LEFT JOIN lkp.TaskPriority AS tp ON tp.TenantId = t.TenantId AND tp.Id = t.TaskPriorityId
LEFT JOIN sec.AppUser AS a ON a.TenantId = t.TenantId AND a.Id = t.AssignedUserId
WHERE t.DeletedAt IS NULL AND p.DeletedAt IS NULL AND EXISTS (SELECT 1 FROM sec.fn_UserHasPermission(t.TenantId, CONVERT(INT, SESSION_CONTEXT(N'UserId')), 'project.view'));
GO
